package org.apache.commons.math3.analysis.differentiation;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.concurrent.atomic.AtomicReference;
import org.apache.commons.math3.exception.DimensionMismatchException;
import org.apache.commons.math3.exception.NumberIsTooLargeException;
import org.apache.commons.math3.util.ArithmeticUtils;
import org.apache.commons.math3.util.FastMath;
import org.apache.commons.math3.util.MathArrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DSCompiler_atan2_TriageGen1Test {

    private static final double EPSILON = 1e-14;











    @Test
    public void testAtan2MultipleElements() {
        // Ensure loops for multiple elements work correctly in both branches
        int parameters = 2;
        int order = 0;
        DSCompiler compiler = DSCompiler.getCompiler(parameters, order);
        int size = compiler.getSize();

        double[] y = new double[size];
        double[] x = new double[size];
        double[] result = new double[size];

        // Mix of positive and negative x to cover both branches if size > 1
        // Note: The logic in the provided code uses x[xOffset] to decide the branch for the WHOLE array
        // which is a specific implementation detail of this DSCompiler.

        // Branch 1: x[0] >= 0
        for (int i = 0; i < size; i++) {
            y[i] = 1.0;
            x[i] = 1.0;
        }
        compiler.atan2(y, 0, x, 0, result, 0);
        for (int i = 0; i < size; i++) {
            Assert.assertEquals(FastMath.atan2(1.0, 1.0), result[i], EPSILON);
        }

        // Branch 2: x[0] < 0
        for (int i = 0; i < size; i++) {
            y[i] = 1.0;
            x[i] = -1.0;
        }
        compiler.atan2(y, 0, x, 0, result, 0);
        for (int i = 0; i < size; i++) {
            Assert.assertEquals(FastMath.atan2(1.0, -1.0), result[i], EPSILON);
        }
    }
}
